// Récupération des données du Webhook
const webhook = $('roadmap').first().json;

// Récupération de la réponse de l'IA simulant le référentiel ROME
const simulation = $input.first().json;

// Extraction du JSON généré par l'IA
const simulationText = simulation.output[0].content[0].text;
const romeData = JSON.parse(simulationText);

// Vérification de la réponse du référentiel
if (romeData.warning && !romeData.expectedSkills?.length) {
  throw new Error(`Simulation ROME : ${romeData.warning}`);
}

if (!Array.isArray(romeData.expectedSkills) || romeData.expectedSkills.length === 0) {
  throw new Error("Aucune compétence attendue n'a été retournée.");
}

// Récupération du profil candidat
const profile = webhook.body.profile;

// Préparation des données pour l'analyse des compétences
return [
  {
    json: {
      candidate: {
        technicalSkills: profile.technicalSkills || [],
        softSkills: profile.softSkills || [],
        transferableSkills: profile.transferableSkills || []
      },
      targetJob: {
        name: romeData.targetJob.name,
        romeCode: romeData.targetJob.romeCode,
        region: profile.region
      },
      expectedSkills: romeData.expectedSkills
    }
  }
];

