// 1. Récupération des résultats précédents
const prepared = $('Préparation données IA').first().json;
const analysis = $('Extraction résultat IA').first().json;
const formations = $('Extraction formations').first().json.formations;
const roadmapResponse = $input.first().json;

// 2. Extraction de la réponse de génération de la roadmap
const roadmapText = roadmapResponse.output[0].content[0].text;
const roadmapData = JSON.parse(roadmapText);

// 3. Transformation des formations au format attendu par le backend
const trainings = formations.map(training => ({
  title: training.title,
  organization: training.organization,
  duration: training.duration,
  level: training.certification || training.level || "Non précisé",
  url: training.url || ""
}));

// 4. Calcul du taux de compatibilité
const totalSkills =
  analysis.acquiredSkills.length + analysis.missingSkills.length;

const compatibility = totalSkills > 0
  ? Math.round((analysis.acquiredSkills.length / totalSkills) * 100)
  : 0;

// 5. Construction de la réponse finale
return [
  {
    json: {
      compatibility,
      existingSkills: analysis.acquiredSkills,
      missingSkills: analysis.missingSkills,
      estimatedDuration: roadmapData.estimatedDuration,
      roadmap: roadmapData.roadmap,
      trainings
    }
  }
];
